#!/usr/bin/env node
// Generated by OrchestKit Claude Plugin
// Created: 2026-10-08
// ============================================================================
// A forked skill whose default is a Workflow call must say what to do without it
// ============================================================================
// WHAT THIS GUARDS (#4672)
//
//   A skill with `context: fork` runs in a forked agent. Measured on CC 2.1.294
//   (claude -p): that agent has the Agent tool but NOT the Workflow tool, even
//   when allowed-tools lists Workflow. /ork:review-pr ran 2 headless reviews on
//   hq-ext#2230 as a single pass with 0 Agent and 0 Workflow calls.
//
//   Every SKILL.md with `context: fork` in its frontmatter that calls
//   `Workflow(` must carry one line that starts with `**Forked run:**` and
//   names the Agent tool, says a single pass is not a fallback, and says to
//   stop with BLOCKED when neither tool is there.
//
//   Fails if: that line is removed from any such skill, or a new forked skill
//   calls Workflow( without it. It also fails if no forked skill calls
//   Workflow( at all (the scan would be broken).
// ============================================================================

import { readdirSync, readFileSync, existsSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.join(path.dirname(fileURLToPath(import.meta.url)), '..', '..', '..');
const SKILLS = path.join(ROOT, 'src', 'skills');

const frontmatter = (text) => {
  const m = /^---\n([\s\S]*?)\n---\n/.exec(text);
  return m ? m[1] : '';
};

const failures = [];
let checked = 0;
for (const name of readdirSync(SKILLS).sort()) {
  const file = path.join(SKILLS, name, 'SKILL.md');
  if (!existsSync(file)) continue;
  const text = readFileSync(file, 'utf8');
  if (!/^context:\s*fork\s*$/m.test(frontmatter(text))) continue;
  if (!/\bWorkflow\(/.test(text)) continue;
  checked += 1;
  const line = text.split('\n').find((l) => l.startsWith('**Forked run:**'));
  const missing = [];
  if (!line) missing.push('a line starting with **Forked run:**');
  else {
    if (!/\bAgent tool\b/.test(line)) missing.push('"Agent tool"');
    if (!/single pass/i.test(line) || !/not a fallback/i.test(line)) missing.push('"a single pass is not a fallback"');
    if (!/\bBLOCKED\b/.test(line)) missing.push('"BLOCKED"');
  }
  if (missing.length) failures.push(`src/skills/${name}/SKILL.md: context: fork + Workflow( but no fork fallback (${missing.join(', ')})`);
}

if (checked === 0) {
  console.log('FAIL: no forked skill calls Workflow(; the scan is broken');
  process.exit(1);
}
for (const f of failures) console.log(`FAIL: ${f}`);
if (failures.length) process.exit(1);
console.log(`PASS: ${checked} forked skills that call Workflow( name the Agent tool fallback`);
